func schema_openshift_api_config_v1_NetworkObservabilitySpec(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "NetworkObservabilitySpec defines the configuration for network observability installation",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"installationPolicy": {
						SchemaProps: spec.SchemaProps{
							Description: "installationPolicy controls whether network observability is installed during cluster deployment. Valid values are \"InstallAndEnable\" and \"NoAction\". When set to \"InstallAndEnable\", ensure that network observability will be installed and enabled on the cluster. If already installed, no action taken, but if it gets uninstalled, it will install it again. When set to \"NoAction\", nothing will be done regarding Network observability. During the installation of NetworkObservability, the platform checks for any existing manual installations. If a successful installation using the OLMv0 or OLMv1 API is detected, it will be used. If the platform cannot determine how the current version was installed, or if the existing installation is incomplete, the installation process will stop.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
				},
				Required: []string{"installationPolicy"},
			},
		},
	}
}

func schema_openshift_api_config_v1_NetworkSpec(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "NetworkSpec is the desired network configuration. As a general rule, this SHOULD NOT be read directly. Instead, you should consume the NetworkStatus, as it indicates the currently deployed configuration. Currently, most spec fields are immutable after installation. Please view the individual ones for further details on each.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"clusterNetwork": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "IP address pool to use for pod IPs. This field is immutable after installation.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: map[string]interface{}{},
										Ref:     ref(v1.ClusterNetworkEntry{}.OpenAPIModelName()),
									},
								},
							},
						},
					},
					"serviceNetwork": {
						VendorExtensible: spec.VendorExtensible{
							Extensions: spec.Extensions{
								"x-kubernetes-list-type": "atomic",
							},
						},
						SchemaProps: spec.SchemaProps{
							Description: "IP address pool for services. Currently, we only support a single entry here. This field is immutable after installation.",
							Type:        []string{"array"},
							Items: &spec.SchemaOrArray{
								Schema: &spec.Schema{
									SchemaProps: spec.SchemaProps{
										Default: "",
										Type:    []string{"string"},
										Format:  "",
									},
								},
							},
						},
					},
					"networkType": {
						SchemaProps: spec.SchemaProps{
							Description: "networkType is the plugin that is to be deployed (e.g. OVNKubernetes). This should match a value that the cluster-network-operator understands, or else no networking will be installed. Currently supported values are: - OVNKubernetes This field is immutable after installation.",
							Default:     "",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"externalIP": {
						SchemaProps: spec.SchemaProps{
							Description: "externalIP defines configuration for controllers that affect Service.ExternalIP. If nil, then ExternalIP is not allowed to be set.",
							Ref:         ref(v1.ExternalIPConfig{}.OpenAPIModelName()),
						},
					},
					"serviceNodePortRange": {
						SchemaProps: spec.SchemaProps{
							Description: "The port range allowed for Services of type NodePort. If not specified, the default of 30000-32767 will be used. Such Services without a NodePort specified will have one automatically allocated from this range. This parameter can be updated after the cluster is installed.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"networkDiagnostics": {
						SchemaProps: spec.SchemaProps{
							Description: "networkDiagnostics defines network diagnostics configuration.\n\nTakes precedence over spec.disableNetworkDiagnostics in network.operator.openshift.io. If networkDiagnostics is not specified or is empty, and the spec.disableNetworkDiagnostics flag in network.operator.openshift.io is set to true, the network diagnostics feature will be disabled.",
							Default:     map[string]interface{}{},
							Ref:         ref(v1.NetworkDiagnostics{}.OpenAPIModelName()),
						},
					},
					"networkObservability": {
						SchemaProps: spec.SchemaProps{
							Description: "networkObservability is an optional field that configures network observability installation during cluster deployment (day-0). When omitted, unless this is a SNO cluster, network observability will be installed if not already present, after that, no action taken.",
							Default:     map[string]interface{}{},
							Ref:         ref(v1.NetworkObservabilitySpec{}.OpenAPIModelName()),
						},
					},
				},
				Required: []string{"clusterNetwork", "serviceNetwork", "networkType"},
			},
		},
		Dependencies: []string{
			v1.ClusterNetworkEntry{}.OpenAPIModelName(), v1.ExternalIPConfig{}.OpenAPIModelName(), v1.NetworkDiagnostics{}.OpenAPIModelName(), v1.NetworkObservabilitySpec{}.OpenAPIModelName()},
	}
}

